import {createDatabase,sql} from '/app/apps/backend/dist/database.js';import {loadConfig} from '/app/apps/backend/dist/config.js';
const c=loadConfig(process.env);if(c.nodeEnv!=='qa')throw Error('QA_ONLY');const db=createDatabase(c);
try{console.log(JSON.stringify(await db.transaction().execute(async tx=>{await sql`SET TRANSACTION READ ONLY`.execute(tx);
const assessments=(await sql`SELECT control_assessment_id::text AS id,tenant_id::text,created_by_user_identity_id::text AS author,
control_id::text,control_version_id::text,methodology_version_ref,effective_configuration_id::text,lifecycle_state,result_status,
domain_conclusion,design_effectiveness,operating_effectiveness,overall_effectiveness,coverage_percent,row_version,created_at,updated_at
FROM controls.control_assessments ORDER BY created_at DESC`.execute(tx)).rows;
const latest=assessments[0];if(!latest)throw Error('QA_ASSESSMENT_MISSING');
const audits=(await sql`SELECT event_code,command_code,outcome,actor_user_identity_id::text,actor_service_principal_id::text,
 aggregate_id::text,occurred_at,after_payload->>'result_status' AS result_status
FROM ops_audit.audit_events WHERE aggregate_id=${latest.id}::uuid ORDER BY occurred_at`.execute(tx)).rows;
return {recorded_at_utc:new Date().toISOString(),scope:'Real authenticated browser QA guard test, not legal evidence or human acceptance',assessments,audits,transaction:'READ_ONLY'};
})));}finally{await db.destroy();}
